@Controller('api/workspaces')
@UseGuards(JwtAuthGuard)
export class WorkspaceController {
  constructor(private readonly workspaceService: WorkspaceService) {}

  @Patch(':workspaceId/billing')
  async updateBillingPlan(
    @Param('workspaceId') workspaceId: string,
    @Body() updateDto: UpdateBillingPlanDto,
    @Req() req: AuthenticatedRequest,
  ) {
    const isOwner = await this.workspaceService.checkUserIsAdmin(workspaceId, req.user.id);
    if (!isOwner) throw new ForbiddenException('You do not have permission to manage this workspace billing');
    return await this.workspaceService.updateSubscriptionPlan(workspaceId, updateDto.planId);
  }
}
